export function getCapColorwayManifest(id: string): (Omit<CapColorwayManifestItem, "id"> & { id: string }) {
  return (
    (ALL_CAPS_MANIFEST_MAP as Record<string, Omit<CapColorwayManifestItem, "id"> & { id: string }>)[id] ??
    CAPS_MANIFEST[0]
  );
}
